package com.projecteden.penalty.controller; import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.penalty.dto.DailyPenaltyResponse;import com.projecteden.penalty.service.DailyPenaltyService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/penalties")public class DailyPenaltyController{private final DailyPenaltyService service;public DailyPenaltyController(DailyPenaltyService service){this.service=service;}@GetMapping("/me")public DailyPenaltyResponse get(@AuthenticationPrincipal User u){return service.get(u.getId());}}
